INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A közzétételkor megadott összefoglalók a nyitott kiadásba gyűlnek. A kiadás lezárása dátumot és verziószámot ad nekik, és megnyit egy újat.','de','Die beim Veröffentlichen angegebenen Zusammenfassungen sammeln sich in der offenen Ausgabe. Beim Abschließen der Ausgabe erhalten sie ein Datum und eine Versionsnummer, und eine neue Ausgabe wird eröffnet.','2026-09-17 22:47:22');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A közzétételkor megadott összefoglalók a nyitott kiadásba gyűlnek. A kiadás lezárása dátumot és verziószámot ad nekik, és megnyit egy újat.','en','The summaries entered at publication are collected in the open release. Closing the release assigns them a date and version number, and opens a new one.','2026-09-17 22:46:54');
