INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A súgó felső szintje. A fejezetek ezekbe vannak besorolva, a sorrend itt állítható. Minden nyelvnek saját modulsora van — az összetartozást a fejezetszám köti össze.','de','Die oberste Ebene der Hilfe. Die Kapitel sind hier eingeordnet, die Reihenfolge lässt sich hier einstellen. Jede Sprache hat ihre eigene Modulreihe — die Zusammengehörigkeit wird über die Kapitelnummer hergestellt.','2026-09-17 22:47:22');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A súgó felső szintje. A fejezetek ezekbe vannak besorolva, a sorrend itt állítható. Minden nyelvnek saját modulsora van — az összetartozást a fejezetszám köti össze.','en','The top level of the help system. Chapters are grouped into these, and the order can be set here. Each language has its own module list — they are linked together by the chapter number.','2026-09-17 22:46:54');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A súgó jelenlegi állapota. A bal oldali fülekről érhető el minden szerkesztési feladat.','de','Der aktuelle Stand der Hilfe. Über die Reiter links sind alle Bearbeitungsaufgaben erreichbar.','2026-09-17 22:47:22');
