INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A törölt fejezetek és modulok <b>nem vesznek el</b>: teljes tartalmukkal ide kerülnek — a szakaszaikkal, a verziótörténetükkel és a képernyő-hozzárendeléseikkel együtt —, és egy kattintással visszaállíthatók. Véglegesen csak innen törlődnek.','de','Gelöschte Kapitel und Module <b>gehen nicht verloren</b>: Sie landen mit ihrem vollständigen Inhalt hier — samt Abschnitten, Versionsverlauf und Bildschirmzuordnungen — und lassen sich mit einem Klick wiederherstellen. Endgültig gelöscht werden sie nur von hier.','2026-09-17 22:47:22');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A törölt fejezetek és modulok <b>nem vesznek el</b>: teljes tartalmukkal ide kerülnek — a szakaszaikkal, a verziótörténetükkel és a képernyő-hozzárendeléseikkel együtt —, és egy kattintással visszaállíthatók. Véglegesen csak innen törlődnek.','en','Deleted chapters and modules are <b>not lost</b>: they are moved here with all their content — including their sections, version history and screen assignments — and can be restored with a single click. They are only deleted permanently from here.','2026-09-17 22:46:54');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('A visszatöltés vázlatot készít — a nyilvános oldal csak közzététel után változik.','de','Das Zurückladen erzeugt einen Entwurf — die öffentliche Seite ändert sich erst nach der Veröffentlichung.','2026-09-17 22:47:22');
