INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('Ez mondja meg, hogy az Infinity egy adott képernyőjén a <b>?</b> gomb melyik fejezetet nyissa meg. Az útvonal az Infinity route-ja, például <span class=\"mono\">penzugy/egyenleg/index','de','Damit wird festgelegt, welches Kapitel die Schaltfläche <b>?</b> auf einem bestimmten Bildschirm von Infinity öffnet. Der Pfad ist die Route von Infinity, zum Beispiel <span class=\"mono\">penzugy/egyenleg/index','2026-09-17 19:49:32');
