INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('Szerepkörök: <b>admin</b> — mindent; <b>editor</b> — fejezetek, modulok, import, fordítás, képernyők, képek; <b>translator</b> — csak a Fordítás fül. A jelszó cseréje nem kötelező; a Beállítások fülön bármikor elvégezhető.','de','Rollen: <b>admin</b> — alles; <b>editor</b> — Kapitel, Module, Import, Übersetzung, Bildschirme, Bilder; <b>translator</b> — nur die Registerkarte Übersetzung. Das Ändern des Passworts ist nicht verpflichtend; es ist jederzeit auf der Registerkarte Einstellungen möglich.','2026-09-17 22:47:36');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('Szerepkörök: <b>admin</b> — mindent; <b>editor</b> — fejezetek, modulok, import, fordítás, képernyők, képek; <b>translator</b> — csak a Fordítás fül. A jelszó cseréje nem kötelező; a Beállítások fülön bármikor elvégezhető.','en','Roles: <b>admin</b> — everything; <b>editor</b> — chapters, modules, import, translation, screens, images; <b>translator</b> — the Translation tab only. Changing the password is optional; you can do it any time on the Settings tab.','2026-09-17 22:47:03');
