INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('import.bevezeto','de','Laden Sie eine <b>.docx</b>-Datei hoch: Das System teilt sie in Kapitel auf, extrahiert die Bilder und <b>vergleicht sie mit dem aktuellen Inhalt</b>. Sie entscheiden je Kapitel, was übernommen wird. Übernommene Inhalte werden zum <b>Entwurf</b> — auf der öffentlichen Seite erscheinen sie erst nach der Veröffentlichung.','2026-09-17 19:51:06');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('import.bevezeto','en','Upload a <b>.docx</b> file: the system splits it into chapters, extracts the images, and <b>compares it with the current content</b>. You decide chapter by chapter what gets imported. Everything imported becomes a <b>draft</b> — it only appears on the public site once published.','2026-09-17 19:48:41');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('import.tagolas','de','Die Gliederung ergibt sich aus den <b>Überschriftenformaten</b>: <b>Überschrift 1</b> = Modul, <b>Überschrift 2</b> = Kapitel, <b>Überschrift 3–5</b> = Abschnitte innerhalb des Kapitels. Die Kapitelnummer wird aus dem Titel gelesen („5.4 Forderungsmanagement“) und dient der Zuordnung zum bestehenden Kapitel. Bilder werden nach dem Hash ihres Inhalts benannt, sodass keine Duplikate entstehen.','2026-09-17 19:51:06');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('import.tagolas','en','The structure comes from the <b>heading styles</b>: <b>Heading 1</b> = module, <b>Heading 2</b> = chapter, <b>Headings 3–5</b> = sections within the chapter. The chapter number is read from the title (\"5.4 Receivables management\") and used to match it to the existing chapter. Images are named after the hash of their content, so they are never duplicated.','2026-09-17 19:48:41');
