INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('kiadas.gyujtes','de','Die bei der Veröffentlichung angegebenen Zusammenfassungen werden in dieser Ausgabe gesammelt. Abschließen können Sie sie im Reiter <a href=\"{url}\">Einstellungen</a>.','2026-09-17 19:51:06');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('kiadas.gyujtes','en','Summaries entered at publication are collected into this release. You can close it on the <a href=\"{url}\">Settings</a> tab.','2026-09-17 19:48:41');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('kiadas.magyarazat','de','Bei jeder Veröffentlichung entsteht eine <b>Zusammenfassung</b>, die in der <b>offenen</b> Ausgabe gesammelt wird. Genau diesen Text sieht der Leser auf der Seite <b>Neuerungen</b>. Das Abschließen der Ausgabe vergibt Datum und Versionsnummer, entfernt die Neuheitsmarkierungen und eröffnet eine neue Ausgabe.','2026-09-17 19:51:06');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('kiadas.magyarazat','en','Every publication creates a <b>summary</b> that is collected into the <b>open</b> release. This is the text readers see on the <b>Updates</b> page. Closing a release gives them a date and version number, removes the \"new\" markers and opens a new one.','2026-09-17 19:48:41');
