INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('kozzetetel.forditas.sugo','de','Eine Übersetzung wird <b>veraltet</b>, sobald du den ungarischen Text nach einer Änderung veröffentlichst — selbst wenn du nur einen Tippfehler korrigiert hast. Mit dieser Option bleiben die Übersetzungen aktuell und die maschinelle Übersetzung startet nicht erneut.','2026-09-17 19:44:36');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('kozzetetel.forditas.sugo','en','A translation becomes <b>outdated</b> when you publish the Hungarian text after a change — even if you only fixed a typo. Tick this and the translations stay up to date, and machine translation will not run again.','2026-09-17 19:40:10');
