INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('torles.fofejezet','de','Hauptkapitel „{nev}“ löschen? Es wandert in allen Sprachen in den Papierkorb und kann von dort wiederhergestellt werden. Das gelingt nur, wenn es in keiner Sprache Kapitel enthält.','2026-09-17 19:43:58');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('torles.fofejezet','en','Delete the main chapter “{nev}”? It will be moved to the Trash in every language, from where it can be restored. This only works if it contains no chapters in any language.','2026-09-17 19:40:22');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('torles.kerdes','de','Dieses Kapitel löschen: „{nev}“? Es wandert samt seiner früheren Versionen in den Papierkorb — von dort mit einem Klick wiederherstellbar, solange du ihn nicht leerst.','2026-09-17 19:43:58');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('torles.kerdes','en','Delete this chapter: “{nev}”? It will be moved to the Trash along with its earlier versions — from there it can be restored with a single click until you empty it.','2026-09-17 19:40:22');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('torles.kukaba.magyarazat','de','Das Kapitel wandert samt seiner früheren Versionen in den <b>Papierkorb</b> — von dort mit einem Klick wiederherstellbar, solange du ihn nicht leerst.','2026-09-17 19:43:58');
