INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('ui.forditas.gomb','en','Machine-translate missing texts','2026-09-17 19:53:01');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('ui.forditas.sugo','de','Die in {nyelv} noch nicht übersetzten Oberflächentexte werden vom eingestellten maschinellen Übersetzer übertragen. Bereits manuell eingegebene Texte bleiben unverändert. Bei vielen Texten kann das eine Minute dauern.','2026-09-17 19:51:24');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('ui.forditas.sugo','en','The configured machine translator will translate the interface texts that are still untranslated in {nyelv}. Anything you typed in manually stays untouched. With many texts this may take a minute.','2026-09-17 19:48:57');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('uitext.bevezeto','de','Das sind die Beschriftungen der Benutzeroberfläche selbst — Schaltflächen, Bezeichnungen, Meldungen. Die linke Spalte zeigt den Text in der Quellsprache, dieser kommt aus dem Code. Was du leer lässt, erscheint in der Quellsprache, die Oberfläche bleibt also nie ohne Beschriftung.','2026-09-17 19:51:24');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('uitext.bevezeto','en','These are the interface\'s own labels — buttons, captions, messages. The left column shows the source text, which comes from the code. Anything you leave empty is shown in the source language, so the interface is never left without a label.','2026-09-17 19:48:57');
