INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('ures.fejezetek','de','Wähle links in der Liste ein Kapitel aus — oder erstelle mit der Schaltfläche <b>+</b> ein neues. Ein Klick auf den Titel des Hauptkapitels öffnet dessen Beschreibung: dort beschreibst du, wozu dieser Menüpunkt dient.','2026-09-17 19:51:24');
