INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('valtozatok.uresen','de','Dieses Kapitel wurde noch nie veröffentlicht, daher gibt es keine Vergleichsgrundlage.<br><span class=\"muted\">Das System speichert bei jeder Veröffentlichung den vorherigen Stand — ab der ersten Veröffentlichung reihen sich die Versionen hier auf, mit den Schaltflächen <b>Vergleichen</b> und <b>Zurückladen</b>.</span>','2026-09-17 19:51:24');
INSERT IGNORE INTO `help_ui` (`ui_key`, `lang`, `text`, `updated_at`) VALUES ('valtozatok.uresen','en','This chapter has never been published, so there is nothing to compare with.<br><span class=\"muted\">The system saves the previous state at every publication — from the first publication on, the versions will be listed here with <b>Compare</b> and <b>Restore</b> buttons.</span>','2026-09-17 19:48:57');
